# -- ported from 0073_backfill_project_file_from_tickets.py --
def backfill_project_file(apps, schema_editor):
    """
    Backfills Configuration.project_file from ProductionTicket.project_file
    for existing shop configurations that are linked to a project file
    via their production ticket but lack the new direct FK.
    """
    try:
        Configuration = apps.get_model("configurator", "Configuration")
        ProductionTicket = apps.get_model("production", "ProductionTicket")
        ContentType = apps.get_model("contenttypes", "ContentType")
    except LookupError:
        # On a fresh DB the production app tables may not exist yet;
        # nothing to backfill in that case.
        return

    config_ct = ContentType.objects.get_for_model(Configuration)

    # Find all configurations that have NO project_file set
    configs_without_pf = Configuration.objects.filter(
        project_file__isnull=True,
        quote__isnull=True,  # Only direct/shop configs
    )

    for config in configs_without_pf:
        ticket = ProductionTicket.objects.filter(
            content_type=config_ct,
            object_id=config.pk,
            project_file__isnull=False,
        ).first()

        if ticket:
            Configuration.objects.filter(pk=config.pk).update(
                project_file=ticket.project_file
            )


